messages.content:
Tool response:
Tool: create_module_with_assignments
Description: Create Module With Assignments
Parameters:
    {
      "type": "object",
      "properties": {
        "course_id": {
          "type": "string",
          "description": "Unique identifier of the course to which the module will be added",
          "title": "Course Id"
        },
        "title": {
          "type": "string",
          "title": "Title",
          "description": "Title of the new module"
        },
        "release_at": {
          "type": "string",
          "title": "Release At",
          "description": "ISO 8601 formatted datetime when the module should be released (UTC)"
        },
        "assignments": {
          "items": {
            "type": "string"
          },
          "type": "array",
          "title": "Assignments",
          "description": "List of auto-graded assignment titles to be attached to the module"
        }
      },
      "required": [
        "course_id",
        "title",
        "release_at",
        "assignments"
      ]
    }
